(function(){"use strict";var STORAGE_PREFIX="nettertech_events_waitlist_";function init(){var panels=document.querySelectorAll(".nte-waitlist");for(var i=0;i<panels.length;i++){initPanel(panels[i])}}function initPanel(container){var occurrenceId=container.getAttribute("data-occurrence-id");var toggle=container.querySelector(".nte-waitlist__toggle");var panel=container.querySelector(".nte-waitlist__panel");var submitBtn=container.querySelector(".nte-waitlist__submit");var successEl=container.querySelector(".nte-waitlist__success");var successText=container.querySelector(".nte-waitlist__success-text");var errorEl=container.querySelector(".nte-waitlist__error");var leaveBtn=container.querySelector(".nte-waitlist__leave");if(!toggle||!panel||!submitBtn){return}if(leaveBtn){leaveBtn.addEventListener("click",function(){var storedData=getStored(occurrenceId);if(!storedData||!storedData.email){return}if(!window.confirm(nettertechEventsWaitlist.i18n.leaveConfirm)){return}leaveBtn.disabled=true;leaveBtn.textContent=nettertechEventsWaitlist.i18n.leaving;fetch(nettertechEventsWaitlist.restUrl+"leave",{method:"POST",headers:{"Content-Type":"application/json","X-WP-Nonce":nettertechEventsWaitlist.nonce},body:JSON.stringify({occurrence_id:parseInt(occurrenceId,10),email:storedData.email,token:storedData.leaveToken||""})}).then(function(response){return response.json().then(function(data){return{ok:response.ok,data:data}})}).then(function(result){if(result.ok){clearStored(occurrenceId);hideSuccess(container,toggle,successEl,submitBtn);leaveBtn.disabled=false;leaveBtn.textContent=nettertechEventsWaitlist.i18n.leaveWaitlist}else{leaveBtn.disabled=false}}).catch(function(){leaveBtn.disabled=false})})}toggle.addEventListener("click",function(){var expanded=toggle.getAttribute("aria-expanded")==="true";if(expanded){closePanel(toggle,panel)}else{openPanel(toggle,panel)}});submitBtn.addEventListener("click",function(){var nameInput=container.querySelector(".nte-waitlist__input--name");var emailInput=container.querySelector(".nte-waitlist__input--email");var phoneInput=container.querySelector(".nte-waitlist__input--phone");var name=nameInput?nameInput.value.trim():"";var email=emailInput?emailInput.value.trim():"";var phone=phoneInput?phoneInput.value.trim():"";if(!name||!email){showError(errorEl,nettertechEventsWaitlist.i18n.requiredFields||"Please fill in all required fields.");if(nameInput){nameInput.setAttribute("aria-invalid",name?"false":"true")}if(emailInput){emailInput.setAttribute("aria-invalid",email?"false":"true")}if(!name&&nameInput){nameInput.focus()}else if(!email&&emailInput){emailInput.focus()}return}if(!isValidEmail(email)){showError(errorEl,nettertechEventsWaitlist.i18n.invalidEmail||"Please enter a valid email address.");if(emailInput){emailInput.setAttribute("aria-invalid","true");emailInput.focus()}return}if(nameInput){nameInput.setAttribute("aria-invalid","false")}if(emailInput){emailInput.setAttribute("aria-invalid","false")}hideError(errorEl);submitBtn.disabled=true;submitBtn.textContent=nettertechEventsWaitlist.i18n.joining;fetch(nettertechEventsWaitlist.restUrl+"join",{method:"POST",headers:{"Content-Type":"application/json","X-WP-Nonce":nettertechEventsWaitlist.nonce},body:JSON.stringify({occurrence_id:parseInt(occurrenceId,10),email:email,name:name,phone:phone||null})}).then(function(response){return response.json().then(function(data){return{ok:response.ok,status:response.status,data:data}})}).then(function(result){if(result.ok){setStored(occurrenceId,{email:email,position:result.data.position,leaveToken:result.data.leave_token||""});showSuccess(container,toggle,panel,successEl,successText,result.data.position)}else{showError(errorEl,result.data.message||nettertechEventsWaitlist.i18n.networkError);submitBtn.disabled=false;submitBtn.textContent=nettertechEventsWaitlist.i18n.joinWaitlist}}).catch(function(){showError(errorEl,nettertechEventsWaitlist.i18n.networkError);submitBtn.disabled=false;submitBtn.textContent=nettertechEventsWaitlist.i18n.joinWaitlist})});var stored=getStored(occurrenceId);if(stored){showSuccess(container,toggle,panel,successEl,successText,stored.position)}}function openPanel(toggle,panel){panel.hidden=false;toggle.setAttribute("aria-expanded","true");toggle.textContent=nettertechEventsWaitlist.i18n.close;panel.offsetHeight;panel.classList.add("nte-waitlist__panel--open");var firstInput=panel.querySelector("input");if(firstInput){firstInput.focus()}}function closePanel(toggle,panel){toggle.setAttribute("aria-expanded","false");toggle.textContent=nettertechEventsWaitlist.i18n.joinWaitlist;panel.classList.remove("nte-waitlist__panel--open");panel.addEventListener("transitionend",function handler(){panel.removeEventListener("transitionend",handler);if(toggle.getAttribute("aria-expanded")==="false"){panel.hidden=true}})}function showSuccess(container,toggle,panel,successEl,successText,position){toggle.hidden=true;panel.hidden=true;panel.classList.remove("nte-waitlist__panel--open");var message=nettertechEventsWaitlist.i18n.position.replace("%d",position);successText.textContent=message;successEl.hidden=false}function hideSuccess(container,toggle,successEl,submitBtn){successEl.hidden=true;toggle.hidden=false;toggle.setAttribute("aria-expanded","false");if(submitBtn){submitBtn.disabled=false;submitBtn.textContent=nettertechEventsWaitlist.i18n.joinWaitlist}}function showError(errorEl,message){if(!errorEl){return}errorEl.textContent=message;errorEl.hidden=false}function hideError(errorEl){if(!errorEl){return}errorEl.hidden=true}function isValidEmail(email){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)}function getStored(occurrenceId){try{var raw=localStorage.getItem(STORAGE_PREFIX+occurrenceId);if(!raw){return null}var data=JSON.parse(raw);if(data.timestamp&&Date.now()-data.timestamp>30*24*60*60*1e3){localStorage.removeItem(STORAGE_PREFIX+occurrenceId);return null}return data}catch(e){return null}}function setStored(occurrenceId,data){try{data.timestamp=Date.now();localStorage.setItem(STORAGE_PREFIX+occurrenceId,JSON.stringify(data))}catch(e){}}function clearStored(occurrenceId){try{localStorage.removeItem(STORAGE_PREFIX+occurrenceId)}catch(e){}}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init)}else{init()}})();